import json
import os
from pathlib import Path


def load_config(path: str) -> dict:
    p = Path(path)
    if not p.is_file():
        return {}
    with open(p) as f:
        return json.load(f)


def save_config(path: str, data: dict) -> None:
    with open(path, "w") as f:
        json.dump(data, f, indent=2)


def _merge(a: dict, b: dict) -> dict:
    out = dict(a)
    out.update(b)
    return out
